{"command":"python - <<'PY'
from more_itertools import chunked
from more_itertools.more import chunked as implementation

assert chunked is implementation
assert list(chunked(range(6), 2)) == [[0, 1], [2, 3], [4, 5]]
result = list(chunked(range(5), 2))
assert result == [[0, 1], [2, 3], [4]]
assert all(isinstance(part, list) for part in result)
try:
    list(chunked(range(5), 2, strict=True))
except ValueError:
    pass
else:
    raise AssertionError('strict=True accepted a partial final chunk')
assert list(chunked(range(4), 2, strict=True)) == [[0, 1], [2, 3]]
try:
    list(chunked(range(1), None, strict=True))
except ValueError:
    pass
else:
    raise AssertionError('strict=True accepted n=None')
print('focused chunked checks passed')
PY"}

